// Patches the MSW service worker so it never handles media requests.
//
// `public/mockServiceWorker.js` is generated by `msw init` (and again by MSW's own postinstall on
// every `npm install`). Its passthrough rebuilds the request with `fetch(clone, { headers })`, and
// a <video> request rebuilt that way loses its `Range` header: the server answers 200 with the
// whole file to every seek. A fetch event the worker does not answer goes to the network as the
// browser made it, so the worker returns early for media.
//
// Runs after every install (`postinstall`) and after `npm run msw:init`. Idempotent. It fails
// loudly when MSW changed the worker so much that the anchor is gone: then this patch needs a look.
// `scripts/msw-worker.test.ts` checks the worker that is served.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const MARKER = '[onecreator:media-bypass]';
const ANCHOR = "addEventListener('fetch', function (event) {\n  const requestInterceptedAt = Date.now()\n";
const BYPASS = `
  // ${MARKER} Added by scripts/patch-msw-worker.mjs, do not remove.
  // Media is never mocked, and a request rebuilt by the passthrough below loses
  // its "Range" header. Left alone, the browser sends it as it made it.
  if (
    event.request.headers.has('range') ||
    event.request.destination === 'video' ||
    event.request.destination === 'audio' ||
    new URL(event.request.url).pathname.startsWith('/media/')
  ) {
    return
  }
`;

const file = process.argv[2] ?? fileURLToPath(new URL('../public/mockServiceWorker.js', import.meta.url));
const source = readFileSync(file, 'utf8');
if (!source.includes(MARKER)) {
  if (!source.includes(ANCHOR)) {
    console.error(`[patch-msw-worker] No encuentro dónde poner el bypass de media en ${file}: MSW cambió el worker. Revisá scripts/patch-msw-worker.mjs.`);
    process.exit(1);
  }
  writeFileSync(file, source.replace(ANCHOR, `${ANCHOR}${BYPASS}`));
  console.log(`[patch-msw-worker] Bypass de media agregado a ${file}`);
}
